         },
         "delivery":{
            "deliveryStatus":"Mr",
            "deliveryDate": "2021-12-21 09:55:00.0",
            "deliveredBy": "MBOESEL-OHIPSB"
         }
      }
   ]
}

Step 4: Delete a Guest Message by ID
